// A module build as a live dashboard: phases, steps with timings, module facts, a progress bar and the tool's own
// output. The build writes to Console.Out like any tool; the session captures those lines into the Output panel.
Step[] plan = {
    new("Prepare", "config", "Read Build/project.build.json", 0.4, StatusKind.Pass, "Loaded project.build.json (3 projects, version 2.0.X)", "Resolved version 2.0.0 from PowerShell Gallery (current 0.0.4)"),
    new("Prepare", "manifest", "Update ConsoleMonster.psd1", 0.5, StatusKind.Pass, "ModuleVersion 0.0.4 -> 2.0.0", "CmdletsToExport: 38 binary cmdlets"),
    // … 13 more lines in the full program
    new("Publish", "publish", "Publish to PowerShell Gallery", 0.3, StatusKind.Skip, "RunMode is Build; publishing is disabled")
};

Phases phases = new Phases();
foreach (string phase in new[] { "Prepare", "Restore", "Build", "Test", "Docs", "Sign", "Package", "Publish" }) {
    phases.Set(phase);
}
StatusList steps = new StatusList("steps");
foreach (Step step in plan) {
    steps.Set(step.Key, step.Label, StatusKind.Pending);
}
KeyValueList module = new KeyValueList("module")
    .Add("Module", "[bold]ConsoleMonster[/]")
    .Add("Version", "0.0.4 [muted]→[/] [bold]2.0.0[/]")
    .Add("Frameworks", "netstandard2.0 · net472 · net8.0")
    .Add("PowerShell", "5.1 Desktop · 7.x Core")
    .Add("Run mode", "Build [muted](publish disabled)[/]")
    .Add("Elapsed", "-");
ProgressBar progress = new ProgressBar("Overall", "overall").Total(plan.Length).LabelWidth(8);

Dashboard dashboard = new DashboardBuilder("[bold]Module build[/]")
    .Subtitle("Build-Module ConsoleMonster")
